[ApiController][Authorize(Roles="Administrator")][Route("api/company/current/personnel-identities")]
public sealed class CompanyPersonnelIdentityController(CompanyPersonnelIdentityService service,TheTechIdeaWeb.Diagnostics.IFailureReporter failures):ControllerBase
{
    [HttpGet] public async Task<ActionResult<CompanyPersonnelIdentityCatalog>> Catalog(){try{return Ok(await service.CatalogAsync(User));}catch(UnauthorizedAccessException denied){failures.ReportHandled(denied,"authorizing company personnel request","request forbidden");return Forbid();}catch(InvalidOperationException error){var failureReference=failures.ReportHandled(error,"processing company personnel request","original evidence or outcome unconfirmed; reconcile before retrying");return Conflict(new{error="The personnel evidence or outcome could not be confirmed. Reconcile the original record before retrying.",reference=failureReference});}}
    [HttpPost("review")] public async Task<ActionResult<CompanyPersonnelIdentityReview>> Review(CompanyPersonnelIdentityQuery query){try{return Ok(await service.ReviewAsync(User,query));}catch(UnauthorizedAccessException denied){failures.ReportHandled(denied,"authorizing company personnel request","request forbidden");return Forbid();}catch(ArgumentException error){var failureReference=failures.ReportHandled(error,"validating company personnel request","request rejected");return BadRequest(new{error="The personnel request is invalid.",reference=failureReference});}catch(InvalidOperationException error){var failureReference=failures.ReportHandled(error,"processing company personnel request","original evidence or outcome unconfirmed; reconcile before retrying");return Conflict(new{error="The personnel evidence or outcome could not be confirmed. Reconcile the original record before retrying.",reference=failureReference});}}
    [HttpPost] public Task<ActionResult<COMPANY_PERSONNEL_IDENTITY>> Record(CompanyPersonnelIdentityCommand command)=>RecordCore(command,false);
    [HttpPost("recovery")] public Task<ActionResult<COMPANY_PERSONNEL_IDENTITY>> Recover(CompanyPersonnelIdentityCommand command)=>RecordCore(command,true);
    private async Task<ActionResult<COMPANY_PERSONNEL_IDENTITY>> RecordCore(CompanyPersonnelIdentityCommand command,bool readOnly){Response.Headers.CacheControl="no-store";try{return Ok(await service.RecordAsync(User,command,readOnly));}catch(UnauthorizedAccessException denied){failures.ReportHandled(denied,"authorizing company personnel request","request forbidden");return Forbid();}catch(ArgumentException error){var failureReference=failures.ReportHandled(error,"validating company personnel request","request rejected");return BadRequest(new{error="The personnel request is invalid.",reference=failureReference});}catch(InvalidOperationException error){var failureReference=failures.ReportHandled(error,"processing company personnel request","original evidence or outcome unconfirmed; reconcile before retrying");return Conflict(new{error="The personnel evidence or outcome could not be confirmed. Reconcile the original record before retrying.",reference=failureReference});}}
    [HttpPost("recovery/reference")] public async Task<ActionResult<CompanyPersonnelIdentityRecovery>> RecoverReference(CompanyPersonnelIdentityReference reference){Response.Headers.CacheControl="no-store";try{return Ok(await service.RecoverReferenceAsync(User,reference));}catch(UnauthorizedAccessException denied){failures.ReportHandled(denied,"authorizing company personnel request","request forbidden");return Forbid();}catch(ArgumentException error){var failureReference=failures.ReportHandled(error,"validating company personnel request","request rejected");return BadRequest(new{error="The personnel request is invalid.",reference=failureReference});}catch(InvalidOperationException error){var failureReference=failures.ReportHandled(error,"processing company personnel request","original evidence or outcome unconfirmed; reconcile before retrying");return Conflict(new{error="The personnel evidence or outcome could not be confirmed. Reconcile the original record before retrying.",reference=failureReference});}}
}
